              border: dark ? "1px solid rgba(148,163,184,0.4)" : "1px solid rgba(51,65,85,0.22)",
              background: dark ? "rgba(30,41,59,0.7)" : "rgba(255,255,255,0.85)",
              color: dark ? "#f8fafc" : "#334155",
